CREATE TABLE IF NOT EXISTS guilds (id text PRIMARY KEY,name text NOT NULL,icon text,locale text NOT NULL DEFAULT 'en-US',automod_enabled boolean NOT NULL DEFAULT true,security_enabled boolean NOT NULL DEFAULT true,leveling_enabled boolean NOT NULL DEFAULT true,economy_enabled boolean NOT NULL DEFAULT true,tickets_enabled boolean NOT NULL DEFAULT true,starboard_enabled boolean NOT NULL DEFAULT false,starboard_threshold integer NOT NULL DEFAULT 3,log_channel_id text,mod_log_channel_id text,welcome_channel_id text,goodbye_channel_id text,welcome_message text,goodbye_message text,ai_enabled boolean NOT NULL DEFAULT false,ai_channel_id text,ai_system_prompt text,security_thresholds jsonb,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS cases (id text PRIMARY KEY,guild_id text NOT NULL REFERENCES guilds(id),type text NOT NULL,target_id text NOT NULL,actor_id text NOT NULL,reason text,metadata jsonb,created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS cases_guild_idx ON cases(guild_id,created_at);
CREATE TABLE IF NOT EXISTS warnings (id text PRIMARY KEY,guild_id text NOT NULL,user_id text NOT NULL,actor_id text NOT NULL,reason text,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS warnings_user_idx ON warnings(guild_id,user_id,created_at);
CREATE TABLE IF NOT EXISTS xp (guild_id text NOT NULL,user_id text NOT NULL,xp integer NOT NULL DEFAULT 0,level integer NOT NULL DEFAULT 1,messages integer NOT NULL DEFAULT 0,updated_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT xp_member_idx UNIQUE(guild_id,user_id)); CREATE INDEX IF NOT EXISTS xp_guild_idx ON xp(guild_id,xp);
CREATE TABLE IF NOT EXISTS xp_rewards (id text PRIMARY KEY,guild_id text NOT NULL,level integer NOT NULL,role_id text,message text,CONSTRAINT xp_reward_unique UNIQUE(guild_id,level));
CREATE TABLE IF NOT EXISTS balances (guild_id text NOT NULL,user_id text NOT NULL,balance integer NOT NULL DEFAULT 0,updated_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT balance_member_idx UNIQUE(guild_id,user_id));
CREATE TABLE IF NOT EXISTS economy_transactions (id text PRIMARY KEY,guild_id text NOT NULL,user_id text NOT NULL,amount integer NOT NULL,type text NOT NULL,metadata jsonb,created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS economy_tx_idx ON economy_transactions(guild_id,user_id,created_at);
CREATE TABLE IF NOT EXISTS economy_items (id text PRIMARY KEY,guild_id text NOT NULL,name text NOT NULL,description text,price integer NOT NULL,stock integer NOT NULL DEFAULT -1,metadata jsonb);
CREATE TABLE IF NOT EXISTS economy_inventory (guild_id text NOT NULL,user_id text NOT NULL,item_id text NOT NULL,quantity integer NOT NULL DEFAULT 0,PRIMARY KEY(guild_id,user_id,item_id));
CREATE TABLE IF NOT EXISTS cooldowns (guild_id text NOT NULL,user_id text NOT NULL,key text NOT NULL,expires_at timestamptz NOT NULL,CONSTRAINT cooldown_unique UNIQUE(guild_id,user_id,key));
CREATE TABLE IF NOT EXISTS audit (id text PRIMARY KEY,guild_id text NOT NULL,actor_id text NOT NULL,action text NOT NULL,target_id text,before jsonb,after jsonb,metadata jsonb,created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS audit_guild_idx ON audit(guild_id,created_at);
CREATE TABLE IF NOT EXISTS config (guild_id text NOT NULL,key text NOT NULL,value jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),CONSTRAINT config_key_idx UNIQUE(guild_id,key));
CREATE TABLE IF NOT EXISTS security_trusted (guild_id text NOT NULL,subject_id text NOT NULL,kind text NOT NULL,PRIMARY KEY(guild_id,subject_id,kind));
CREATE TABLE IF NOT EXISTS security_events (id text PRIMARY KEY,guild_id text NOT NULL,type text NOT NULL,actor_id text,target_id text,severity text NOT NULL,metadata jsonb,created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS security_event_idx ON security_events(guild_id,created_at);
CREATE TABLE IF NOT EXISTS tickets (id text PRIMARY KEY,guild_id text NOT NULL,channel_id text NOT NULL,user_id text NOT NULL,panel_id text,category_id text,claimed_by text,status text NOT NULL DEFAULT 'open',subject text,created_at timestamptz NOT NULL DEFAULT now(),closed_at timestamptz); CREATE INDEX IF NOT EXISTS tickets_guild_idx ON tickets(guild_id,status);
CREATE TABLE IF NOT EXISTS ticket_panels (id text PRIMARY KEY,guild_id text NOT NULL,channel_id text NOT NULL,message_id text NOT NULL,category_id text,staff_role_id text,title text NOT NULL,description text,form jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS transcripts (id text PRIMARY KEY,guild_id text NOT NULL,ticket_id text NOT NULL,content text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS giveaways (id text PRIMARY KEY,guild_id text NOT NULL,channel_id text NOT NULL,message_id text,prize text NOT NULL,winner_count integer NOT NULL,ends_at timestamptz NOT NULL,requirements jsonb,status text NOT NULL DEFAULT 'running',winners jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS giveaway_entries (giveaway_id text NOT NULL,user_id text NOT NULL,entered_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(giveaway_id,user_id));
CREATE TABLE IF NOT EXISTS role_panels (id text PRIMARY KEY,guild_id text NOT NULL,channel_id text NOT NULL,message_id text NOT NULL,title text NOT NULL,exclusive boolean NOT NULL DEFAULT false,roles jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS autoroles (guild_id text NOT NULL,role_id text NOT NULL,type text NOT NULL,PRIMARY KEY(guild_id,role_id,type));
CREATE TABLE IF NOT EXISTS starboard (guild_id text NOT NULL,message_id text NOT NULL,channel_id text NOT NULL,star_message_id text,count integer NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(guild_id,message_id));
CREATE TABLE IF NOT EXISTS polls (id text PRIMARY KEY,guild_id text NOT NULL,channel_id text NOT NULL,message_id text NOT NULL,question text NOT NULL,options jsonb NOT NULL,ends_at timestamptz,status text NOT NULL DEFAULT 'open',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS poll_votes (poll_id text NOT NULL,user_id text NOT NULL,option integer NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(poll_id,user_id));
CREATE TABLE IF NOT EXISTS suggestions (id text PRIMARY KEY,guild_id text NOT NULL,channel_id text NOT NULL,message_id text NOT NULL,user_id text NOT NULL,content text NOT NULL,status text NOT NULL DEFAULT 'pending',staff_response text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS suggestion_votes (suggestion_id text NOT NULL,user_id text NOT NULL,value integer NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(suggestion_id,user_id));
CREATE TABLE IF NOT EXISTS events (id text PRIMARY KEY,guild_id text NOT NULL,channel_id text NOT NULL,message_id text,title text NOT NULL,description text,starts_at timestamptz NOT NULL,timezone text NOT NULL DEFAULT 'UTC',status text NOT NULL DEFAULT 'scheduled',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS event_rsvps (event_id text NOT NULL,user_id text NOT NULL,status text NOT NULL DEFAULT 'going',created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(event_id,user_id));
CREATE TABLE IF NOT EXISTS analytics (id text PRIMARY KEY,guild_id text NOT NULL,type text NOT NULL,user_id text,channel_id text,value integer NOT NULL DEFAULT 1,metadata jsonb,created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS analytics_guild_idx ON analytics(guild_id,type,created_at);
CREATE TABLE IF NOT EXISTS backups (id text PRIMARY KEY,guild_id text NOT NULL,actor_id text NOT NULL,payload jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS translations (id text PRIMARY KEY,guild_id text NOT NULL,source text NOT NULL,target text NOT NULL,provider text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ai_messages (id text PRIMARY KEY,guild_id text NOT NULL,channel_id text NOT NULL,user_id text NOT NULL,role text NOT NULL,content text NOT NULL,created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS ai_history_idx ON ai_messages(guild_id,channel_id,created_at);
